/****
 * Resource Registry
 *
 * Project-scoped registry for MCP resources. Each project has its own
 * isolated resource namespace, preventing cross-project resource access.
 *
 * @module
 */
import { matchResourcePattern } from "./pattern.js";
import { ScopedRegistryFacade } from "../registry/scoped-registry-facade.js";
import { ProjectScopedRegistryManager } from "../registry/project-scoped-registry-manager.js";
const resourceRegistryManager = new ProjectScopedRegistryManager("resource");
class ResourceRegistry extends ScopedRegistryFacade {
    findByPattern(uri, include = () => true) {
        const resources = Array.from(this.getAll().values()).filter(include);
        for (const resource of resources) {
            if (resource.pattern === uri)
                return resource;
        }
        for (const resource of resources) {
            if (this.matchPattern(uri, resource.pattern))
                return resource;
        }
        return undefined;
    }
    matchPattern(uri, pattern) {
        return matchResourcePattern(uri, pattern);
    }
    extractParams(uri, pattern) {
        return this.matchPattern(uri, pattern) ?? {};
    }
    list() {
        return this.getAllIds();
    }
}
/** Shared resource registry value. */
export const resourceRegistry = new ResourceRegistry(resourceRegistryManager);
